sentences = ['spark hadoop', 'spark flink', 'hadoop hive']

words = []
for s in sentences:
    words.extend(s.split(' '))          # 模拟 flatMap：拆词并拍平

counts = {}
for w in words:
    counts[w] = counts.get(w, 0) + 1    # 模拟 reduceByKey：按单词聚合

for w in sorted(counts):                # 字典序输出
    print('%s %d' % (w, counts[w]))
